module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0]dout_parallel,
    output reg dout_valid
);

reg [3:0] cnt;
localparam IDLE = 0;
localparam LOADING = 1;
localparam DONE = 2;
reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        cnt <= 0;
        dout_parallel <= 0;
        dout_valid <= 0;
        state <= IDLE;
    end 
    else begin
        case(state)
            IDLE: begin
                if(din_valid) begin
                    dout_parallel[7] <= din_serial;
                    cnt <= cnt + 1;
                    if(cnt == 4'd7) begin
                        state <= LOADING;
                    end
                end
            end
            LOADING: begin
                if(din_valid) begin
                    dout_parallel[6-cnt] <= din_serial;
                    cnt <= cnt + 1;
                    if(cnt == 4'd7) begin
                        state <= DONE;
                    end
                end
            end
            DONE: begin
                dout_valid <= 1;
                if(din_valid) begin
                    dout_parallel[5-cnt] <= din_serial;
                    cnt <= cnt + 1;
                    if(cnt == 4'd7) begin
                        state <= IDLE;
                    end
                end
            end
        endcase
    end
end

endmodule
